import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial, DoubleSide } from 'three/webgpu';
import { mix, smoothstep, uv, color, add, mul, texture, varying } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Array<{name:string, params:any, trigger:string}>} cinematicPrimitives
 * @property {string} imageUrl
 * @property {string} [depthMapUrl]
 * @property {string} [meshUrl]
 * @property {Object} [colors]
 * @property {Array<{at:number,hex:string}>} [colors.gradientStops]
 * @property {Array<{text:string,role:string,typography?:{fontSize?:number}}>} [textContent]
 * @property {Object} [intent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {{loadTexture:(url:string)=>Promise<any>}} textureLoader
 * @property {{loadGLB:(url:string)=>Promise<any>}} glbLoader
 * @property {{loadVideo?:(url:string)=>Promise<any>}} videoLoader
 * @property {{createText:(content:string,opts?:any)=>any}} fontAtlas
 * @property {{[key:string]:(target:any,params:any)=>{timeline:any,cleanup:()=>void}}} primitives
 * @property {(event:string,payload:any)=>void} emit
 * @property {string} [tier]
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CylinderGeometry, TorusKnotGeometry, DirectionalLight, AmbientLight, Color } = ctx.THREE;

  const root = new Group();

  // ---------- Backdrop Gradient Plane ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const uvNode = uv();

  const stops = (config.colors && config.colors.gradientStops) || [];
  // default to three stops if not provided
  const stop0 = stops[0] || { at: 0, hex: '#0b0b10' };
  const stop1 = stops[1] || { at: 0.7, hex: '#101017' };
  const stop2 = stops[2] || { at: 1, hex: '#16161d' };

  const c0 = color(new Color(stop0.hex));
  const c1 = color(new Color(stop1.hex));
  const c2 = color(new Color(stop2.hex));

  const t01 = smoothstep(stop0.at, stop1.at, uvNode.y);
  const mix01 = mix(c0, c1, t01);
  const t12 = smoothstep(stop1.at, stop2.at, uvNode.y);
  const finalColor = mix(mix01, c2, t12);

  const backdropMat = new MeshStandardNodeMaterial({
    colorNode: finalColor,
    side: DoubleSide,
  });

  const backdropMesh = new Mesh(backdropGeom, backdropMat);
  backdropMesh.position.set(0, 0, -3);
  root.add(backdropMesh);

  // ---------- Ambient Light ----------
  const ambient = new AmbientLight(0xffffff, 0.6);
  root.add(ambient);

  // ---------- Key Directional Light ----------
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 3, 2);
  root.add(keyLight);

  // ---------- Rim / Back Light ----------
  const rimLight = new DirectionalLight(0xffffff, 0.8);
  rimLight.position.set(-2, 2, -2);
  root.add(rimLight);

  // ---------- Pedestal ----------
  const pedestalGeom = new CylinderGeometry(1.1, 1.1, 0.5, 32);
  const pedestalMat = new MeshStandardNodeMaterial({
    color: new Color('#14141a'),
    roughness: 0.7,
    metalness: 0.35,
    side: DoubleSide,
  });
  const pedestalMesh = new Mesh(pedestalGeom, pedestalMat);
  // top face at y = -0.35 => center y = -0.35 - height/2
  pedestalMesh.position.set(0, -0.35 - 0.25, 0);
  root.add(pedestalMesh);

  // ---------- Contact Shadow ----------
  const shadowGeom = new PlaneGeometry(3, 3);
  // radial gradient using nodes
  const uvShadow = uv();
  const dist = mul(uvShadow.x.sub(0.5).pow(2).add(uvShadow.y.sub(0.5).pow(2)), 4.0); // rough approximation
  const opacityNode = smoothstep(0.0, 0.4, dist);
  const shadowMat = new MeshStandardNodeMaterial({
    transparent: true,
    opacityNode: mul(0.6, opacityNode), // center 0.6 fade out
    side: DoubleSide,
    color: new Color('#000000'),
  });
  const shadowMesh = new Mesh(shadowGeom, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -0.36, 0);
  root.add(shadowMesh);

  // ---------- Torus Knot ----------
  const knotGeom = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshStandardNodeMaterial({
    color: new Color('#ffffff'), // will be modulated by texture roughness map
    roughness: 0.55,
    metalness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
    anisotropy: 0.9,
    side: DoubleSide,
  });

  const knotMesh = new Mesh(knotGeom, knotMat);
  knotMesh.position.set(0, 0.4, 0);
  root.add(knotMesh);

  // Load brushed metal texture and assign as roughness map (center 0.9 multiplier)
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((tex) => {
    // texture node for roughness
    const texNode = texture(tex);
    // multiply by 0.9 to shift center while keeping map integrity
    const roughnessNode = mul(texNode.r, 0.9);
    knotMat.roughnessNode = roughnessNode;
    knotMat.needsUpdate = true;

    // also use the texture as a normal map placeholder (scratch noise not provided)
    // if you have a separate normal texture you could assign here
    knotMat.normalMap = tex;
    knotMat.normalScale.set(0.15, 0.15);
    knotMat.needsUpdate = true;
  });

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const isHeadline = item.role === 'headline' || (item.typography && item.typography.fontSize && item.typography.fontSize > 30);
    const fontSize = isHeadline ? 68 : 18;
    const colorHex = '#e8ecf2'; // paper color from palette
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: colorHex,
      align: 'left',
    });
    const yPos = isHeadline ? -1.2 : -1.6;
    textObj.position.set(-3.0 + 0.5, yPos, 0.1); // left aligned with a small inset
    root.add(textObj);
  }

  // ---------- Cinematic Primitives ----------
  const primitiveCleanups = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const result = fn(root, prim.params ?? {});
        primitiveCleanups.push(result);
      }
    }
  }

  // ---------- UserData ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    // dispose textures if any
    texturePromise.then((tex) => {
      tex.dispose();
    }).catch(() => {});

    // cleanup primitives
    for (const p of primitiveCleanups) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }

    // kill any GSAP timelines (none created directly here but guard)
    gsap.globalTimeline.clear(true);
  };

  return root;
}
